    root_index = -1

    for i, (v, l, r) in enumerate(vertices):
        nodes[i] = TreeNode(v)
        if l != -1:
            nodes[i].left = nodes[l]
        if r != -1:
            nodes[i].right = nodes[r]
        if l == -1 and root_index == -1:
            root_index = i

    return nodes[root_index]

def count_fails(root: TreeNode) -> int:
    def dfs(node: TreeNode, target: int) -> bool:
        if node is None:
            return False
        if node.value == target:
            return True
        if target < node.value:
            return dfs(node.left, target)
        else:
            return dfs(node.right, target)

    visited = {}
    total_fails = 0

    def traverse(node: TreeNode):
        if node is None:
            return
        if node.value not in visited:
            visited[node.value] = 0
        if not dfs(node, node.value):
            total_fails += 1
        traverse(node.left)
        traverse(node.right)

    traverse(root)
    return total_fails

