from typing import List

class TreeNode:
    def __init__(self, value: int, left: 'TreeNode' = None, right: 'TreeNode' = None):
        self.value = value
        self.left = left
        self.right = right

def count_failures(n: int, nodes: List[List[int]]) -> int:
    # Create tree nodes based on input
    tree = [None] * n
    for i, (v, l, r) in enumerate(nodes):
        tree[i] = TreeNode(v)

    for i, (_, l, r) in enumerate(nodes):
        if l != -1:
            tree[i].left = tree[l]
        if r != -1:
            tree[i].right = tree[r]

    root_index = nodes[0][1]
    root = tree[root_index]

    def dfs(node: TreeNode, target: int) -> bool:
        if node is None:
            return False
        if node.value == target:
            return True
        if target < node.value:
            return dfs(node.left, target)
        else:
            return dfs(node.right, target)

    failure_count = 0
    for i, (_, _, _) in enumerate(nodes):
        if not dfs(root, i + 1):
            failure_count += 1

    return failure_count

